# Content and components for the supplied 33-page proposal.
def tr(l,sq,en,de): return {"sq":sq,"en":en,"de":de}[l]
PAGES=["index","services","projects","partners","creative","ai-agents","about","contact","krakenos"]
NAV_ORDER=['index','services','projects','partners','krakenos','creative','ai-agents','about','contact']
def labels(l): return tr(l,["Kreu","Shërbimet","Projektet","Partnerët","Kreativa","AI Agents","Rreth nesh","Kontakt","KrakenOS"],["Home","Services","Projects","Partners","Creative","AI Agents","About us","Contact","KrakenOS"],["Start","Leistungen","Projekte","Partner","Kreativ","KI-Agenten","Über uns","Kontakt","KrakenOS"])
