def partner_card(i,p,l,teaser=False):
 key,name,file,(w,h),desc,tone=p
 # The name is printed next to the logo, so the logo itself is decorative.
 logo=f'<span class="partner-mark" data-logo="{key}"><img src="assets/partners/{file}" alt="" width="{w}" height="{h}" loading="lazy"{" class=tone" if tone else ""}></span>'
 if teaser: return f'<a class="partner-card card" href="{route("partners",l)}#partner-{key}">{logo}<div class="partner-copy"><h3>{name}</h3><p>{tr(l,*desc)}</p></div><span class="card-arrow" aria-hidden="true">↗</span></a>'
 return f'<article class="partner-card card" id="partner-{key}">{logo}<div class="partner-copy"><p class="partner-index">{i+1:02d} / PARTNER</p><h2>{name}</h2><p>{tr(l,*desc)}</p></div></article>'
def partner_rows(l,t,teaser=False):
 # Home: the first six partners and a link to the full list.
 action=f'<a class="text-link" href="{route("partners",l)}">{tr(l,"Shiko të gjithë partnerët","See all partners","Alle Partner ansehen")}{A}</a>'
 return '<section class="wrap section partner-section">'+heading(labels(l)[3],tr(l,'Njerëzit dhe platformat me të cilat ndërtojmë.','The people and platforms we build with.','Menschen und Plattformen, mit denen wir Lösungen entwickeln.'),action=action)+'<div class="partner-grid">'+''.join(partner_card(i,p,l,True) for i,p in enumerate(PARTNERS[:6]))+'</div></section>'
