 portfolio=heading(t['work'],tr(l,'Identitete me karakter.','Identities with character.','Identitäten mit Charakter.'))+filters('portfolio',[('all',c['all']),('nexus','NEXUS'),('hyperlink','HYPERLINK')],l)+'<div class="grid two">'+''.join(brandbook(k,l,t).replace('data-filter-item="projects" data-category="creative"',f'data-filter-item="portfolio" data-category="{k}"') for k in ['nexus','hyperlink'])+'</div>'
