 flow=tr(l,['Kërkesa','Agjenti','Aprovimi','Veprimi'],['Request','Agent','Approval','Action'],['Anfrage','Agent','Freigabe','Aktion'])
 hero=f'<section class="ai-hero wrap"><div><p class="eyebrow"><span class="live-dot"></span>IT DEPARTMENT / AI AGENTS</p><h1>{title[0]}<br><span>{title[1]}</span></h1><p class="lead">{t["aiLead"]}</p><div class="actions">{button(tr(l,"Zgjidh agjentin","Choose an agent","Agenten wählen"),'#agents')}{button(tr(l,"Nis një pilot","Start a pilot","Pilotprojekt starten"),'#brief',style='outline')}</div></div><div class="ai-flow-card"><div class="agent-orbit">{icon(2)}<span>AI</span></div><div class="ai-flow">'+''.join(f'<div><small>0{i+1}</small><strong>{s}</strong></div>' for i,s in enumerate(flow))+'</div><p>'+tr(l,'Rregulla të qarta. Kontroll njerëzor.','Clear rules. Human oversight.','Klare Regeln. Menschliche Kontrolle.')+'</p></div></section>'
