 pilot=tr(l,['Auditim','Rasti i përdorimit','Pilot','Integrim','Monitorim'],['Audit','Use case','Pilot','Integration','Monitoring'],['Analyse','Anwendungsfall','Pilot','Integration','Monitoring'])
 return hero+'<section class="wrap section" id="agents">'+heading('AI AGENTS',tr(l,'Secili me një rol të qartë.','Each with a clear role.','Jeder mit einer klaren Rolle.'))+'<div class="grid three">'+agents+'</div></section><section class="wrap section"><div class="integration-band"><h2>'+tr(l,'Lidhet me mënyrën si punon.','Connects with how you work.','Verbunden mit Ihren Abläufen.')+'</h2><div class="chips">'+''.join(f'<span>{s}</span>' for s in ['WhatsApp','Email','CRM',tr(l,'Formularë','Forms','Formulare'),tr(l,'Tabela & dokumente','Tables & documents','Tabellen & Dokumente')])+'</div><p>'+tr(l,'Integrimet konfigurohen për çdo projekt, me qasjet dhe miratimet përkatëse.','Integrations are configured per project, with the required access and approvals.','Integrationen werden je Projekt mit den erforderlichen Zugängen und Freigaben eingerichtet.')+'</p></div></section><section class="wrap section"><div class="creative-process">'+''.join(f'<div><span>0{i+1}</span><h3>{s}</h3></div>' for i,s in enumerate(pilot))+'</div></section><section class="wrap guard-card">'+icon(1)+f'<div><h2>{t["aiguard"]}</h2><p>{t["aiguardbody"]}</p></div></section>'+brief(l,t,'ai',tr(l,'Cilën punë ta lehtësojmë?','Which task can we make easier?','Welche Aufgabe können wir erleichtern?'),tr(l,'Zgjedhim një rast të qartë dhe e provojmë me ekipin tënd.','We choose a clear use case and test it with your team.','Wir wählen einen klaren Anwendungsfall und testen ihn mit Ihrem Team.'))
