 modules=tr(l,[('CRM & shitje','Nga kontakti te marrëdhënia me klientin.',['Klientë dhe kontakte','Mundësi dhe ndjekje','Aktivitete dhe histori']),('Workspace','Një vend për njerëzit dhe punën.',['Ekipi dhe detyrat','Projektet dhe afatet','Koordinimi i punës']),('Financa & kontabilitet','Pamje e lidhur e pjesës financiare.',['Fatura dhe shpenzime','Raporte financiare','Të dhëna sipas rolit']),('Dokumente & komunikim','Informacioni pranë procesit.',['Dokumente dhe skedarë','Komunikimi i ekipit','AURA dhe mjete të përbashkëta'])],[('CRM & sales','From first contact to customer relationship.',['Customers and contacts','Opportunities and follow-up','Activity and history']),('Workspace','A place for people and work.',['Team and tasks','Projects and deadlines','Work coordination']),('Finance & accounting','A connected view of finances.',['Invoices and expenses','Financial reports','Role-based information']),('Documents & communication','Information close to the process.',['Documents and files','Team communication','AURA and shared tools'])],[('CRM & Vertrieb','Vom ersten Kontakt zur Kundenbeziehung.',['Kunden und Kontakte','Chancen und Nachverfolgung','Aktivitäten und Verlauf']),('Workspace','Ein Ort für Menschen und Arbeit.',['Team und Aufgaben','Projekte und Termine','Arbeitskoordination']),('Finanzen & Buchhaltung','Ein verbundener Blick auf die Finanzen.',['Rechnungen und Ausgaben','Finanzberichte','Rollenbezogene Informationen']),('Dokumente & Kommunikation','Informationen nah am Ablauf.',['Dokumente und Dateien','Teamkommunikation','AURA und gemeinsame Werkzeuge'])])
 cards=''.join(f'<article class="card padded module-card">{icon(i)}<h3>{title}</h3><p>{desc}</p><details><summary>{c["details"]}<span aria-hidden="true">+</span></summary><ul>'+''.join(f'<li>{esc(x)}</li>' for x in items)+'</ul></details></article>' for i,(title,desc,items) in enumerate(modules))
